const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const seattle = ee.Geometry.Point([-122.3321, 47.6062]);
  const startDate = '2021-11-01';
  const endDate = '2021-11-30';

  // 2. Data Acquisition & Check
  // CHIRPS provides daily precipitation in mm
  let precipCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(seattle);

  const colSize = precipCol.size().getInfo();
  console.log(`CHIRPS images found: ${colSize}`);

  if (colSize === 0) {
    console.log("No precipitation data available for November 2021.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum all daily precipitation
  const totalPrecip = precipCol.select('precipitation').sum();

  // 4. Calculate total precipitation in mm
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: seattle,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const precipMm = stats.precipitation;

  // 5. Validation & Final Answer
  if (precipMm === null || precipMm === undefined || isNaN(precipMm)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check for unrealistic values
  if (precipMm < 0 || precipMm > 1000) {
    console.log(`Unrealistic precipitation value: ${precipMm}mm`);
    console.log("<answer>C3</answer>");
    return;
  }

  const precipCm = precipMm / 10;
  console.log(`Total precipitation in November 2021: ${precipMm.toFixed(1)}mm (${precipCm.toFixed(1)}cm)`);
  console.log(`Images processed: ${colSize}`);

  // 20cm = 200mm
  if (precipCm < 20) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
